# ---- THE ALIGNMENT ENGINE (E2/E3/E4's, with a book field) ---------------------------------------------------
def norm(w):
    w = re.sub(r'^ו', '', w); w = re.sub(r'^[הלכב]', '', w) if len(w) > 3 else w
    return w
def bag(k): return collections.Counter(norm(w) for w in toks(*k))
def jac(a, b):
    A, B = bag(a), bag(b); i = sum((A & B).values()); u = sum((A | B).values()); return i / u if u else 0
NUM = {'אחד', 'אחת', 'שני', 'שתי', 'שנים', 'שלש', 'שלשה', 'ארבע', 'חמש', 'שש', 'שבע', 'שבעת', 'עשר', 'עשרה', 'עשרים', 'שלשים', 'ארבעים', 'חמשים', 'מאה', 'מאת', 'אלף', 'אלפים', 'שתים', 'ששת', 'שבעים', 'שלשת'}
def align(spec, run, th=0.3):
    matched = {}; used = set()
    for s in spec:
        best = max(((jac(s, r), r) for r in run if r not in used), default=(0, None))
        if best[0] >= th: matched[s] = (best[1], round(best[0], 2)); used.add(best[1])
    return {'spec': len(spec), 'run': len(run), 'matched': len(matched), 'pairs': matched,
            'dropped': ['%d:%d' % s[1:] for s in spec if s not in matched], 'unmatched': ['%d:%d' % r[1:] for r in run if r not in used]}
def delta(a, b):
    A, B = bag(a), bag(b); return (sorted((B - A).elements()), sorted((A - B).elements()))
# (a) THE SECOND SEAT — 34:18-26 against 23:12-19 and 13:12-13, clause by clause
REPEAT = [('matzah', ('Exod', 23, 15), ('Exod', 34, 18)), ('firstborn_a', ('Exod', 13, 12), ('Exod', 34, 19)), ('firstborn_b', ('Exod', 13, 13), ('Exod', 34, 20)),
          ('rest', ('Exod', 23, 12), ('Exod', 34, 21)), ('feasts', ('Exod', 23, 16), ('Exod', 34, 22)), ('appear', ('Exod', 23, 17), ('Exod', 34, 23)),
          ('leaven_fat', ('Exod', 23, 18), ('Exod', 34, 25)), ('firstfruits_kid', ('Exod', 23, 19), ('Exod', 34, 26))]
R_JAC = {n: round(jac(a, b), 2) for n, a, b in REPEAT}
assert R_JAC == {'matzah': 0.7, 'firstborn_a': 0.26, 'firstborn_b': 0.5, 'rest': 0.26, 'feasts': 0.23, 'appear': 0.69, 'leaven_fat': 0.5, 'firstfruits_kid': 1.0}, R_JAC
R_DELTA = {n: delta(a, b) for n, a, b in REPEAT}
assert R_DELTA['matzah'] == (['אביב', 'חדש'], ['בו', 'יראו', 'לא', 'פני', 'ריקם']), R_DELTA['matzah']
assert R_DELTA['firstborn_b'] == (['חמור', 'יראו', 'לא', 'ניך', 'פני', 'ריקם'], ['אדם', 'בניך', 'חמר', 'כל']), R_DELTA['firstborn_b']
