assert R_DELTA['feasts'] == (['אסיף', 'חטים', 'לך', 'שבעת', 'תעשה', 'תקופת'], ['אסף', 'אספך', 'אשר', 'את', 'מן', 'מעשיך', 'מעשיך', 'צאת', 'שדה', 'שדה', 'תזרע']), R_DELTA['feasts']
