PICKUP = [('25:15', '40:20', 'בדים'), ('25:16', '40:20', 'העדת'), ('25:21', '40:20', 'הכפרת'), ('25:22', '40:20', 'הכפרת'), ('25:30', '40:23', 'לחם'), ('25:37', '40:25', 'נרת'),
          ('26:30', '40:18', 'המשכן'), ('26:33', '40:21', 'פרכת'), ('26:34', '40:20', 'הכפרת'), ('26:35', '40:22', 'השלחן'), ('26:35', '40:24', 'המנרה'), ('26:37', '40:28', 'מסך'),
          ('27:20', '40:25', 'נר'), ('27:21', '40:25', 'לפני')]
def shares(a, b, sub):
    ka = ('Exod',) + tuple(map(int, a.split(':'))); kb = ('Exod',) + tuple(map(int, b.split(':')))
    return any(sub in w for w in toks(*ka)) and any(sub in w for w in toks(*kb))
assert all(shares(a, b, s) for a, b, s in PICKUP), [(a, b, s) for a, b, s in PICKUP if not shares(a, b, s)]
PICKED = sorted(set(a for a, b, s in PICKUP));                             assert len(PICKED) == 13, PICKED
