# ---- F1: THE COVENANT'S OWN CLAUSES (34:10-17) ----------------------------------------------------------------
def covenant(q):
    if q == 'cut_four':
        return cell(c_karat34, I, "the cutting verb at four seats of the chapter — %s: 34:10 'behold I CUT a covenant', 34:12 and 34:15 'lest you CUT a covenant with the inhabitant' (the ban, twice), 34:27 'I have CUT a covenant with you and with Israel' (the sealing) — the chapter opens and closes on the verb and bans it in between" % (c_karat34,), ['covenant_cut'])
    if q == 'wonders':
        return cell(2, I, "34:10 'wonders which have NOT BEEN CREATED in all the earth' — the niphal of the creation verb at %s alone in the Tanakh (Isaiah's 'created now, not long ago' the second seat)" % (fmt(c_nivreu),), ['covenant_cut'])
    if q == 'nations_seven_orders':
        return cell(7, I, "the nations' list at seven seats of Exodus and Deuteronomy in SEVEN DIFFERENT ORDERS: %s — 34:11 names six (Amorite first), 33:2 six (Canaanite first), 23:23 six (Amorite first but the Canaanite fourth), 13:5 five, 23:28 three, Deut 7:1 seven with the Girgashite: no two seats agree on the order and only Deuteronomy has the seventh" % (c_nations,), ['nations_driven_out'])
    if q == 'no_covenant_by_call':
        return cell(ORD_NOCOV, P, "34:12, 34:15 'lest you cut a covenant with the inhabitant of the land' — the first seat is 23:32's ban: cold_run_ordinances.land(no_covenant) -> %r; (not_dwell) -> %r [IMPORT, live call]" % (ORD_NOCOV, ORD_NOTDWELL), ['covenant_barred'])
    if q == 'demolition_grows':
        return cell([3, 4, 5], I, "34:13 'their altars you shall BREAK DOWN, their pillars SHATTER, their asherim CUT DOWN' — THREE verbs; Deut 7:5 FOUR (break down, shatter, cut down, BURN); Deut 12:3 FIVE (break down, shatter, burn, cut down, DESTROY THE NAME): %s — the demolition list grows by one at each later seat" % (c_demolish,), ['demolished'])
    if q == 'demolition_first_seat':
        return cell(ORD_BREAK, P, "23:24's 'you shall utterly demolish them and utterly break their pillars' is the first seat (two verbs, each doubled): cold_run_ordinances.land(break_pillars) -> %r [IMPORT, live call] — 34:13 replaces the doubling with a third object" % (ORD_BREAK,), ['demolished'])
    if q == 'asherav_homograph':
        return cell(4, I, "'his asherim' (אשריו) at %s — the consonants of 34:13's cult-trees are 'happy is he' (ashrav) at the three seats of Proverbs and Psalms: a homograph the census must not count" % (fmt(c_asherav),), ['demolished'])
    if q == 'pillars_exod':
        return cell(3, I, "the pillar-word in Exodus at %s — 23:24 'their pillars' (break), 24:4 'twelve pillars' (Moses builds them at the covenant), 34:13 'their pillars' (shatter): the covenant's own pillars stand between the two bans" % (fmt(c_matzevah_exod),), ['demolished'])
    if q == 'el_acher':
        return cell(1, I, "34:14 'you shall not bow to ANOTHER GOD' (לאל אחר) — the singular 'another god' a hapax (the Torah elsewhere writes 'other gods'); 'for the LORD, JEALOUS is His name, a jealous God is He' — the jealous-word at %d seats (%s)" % (len(c_kanna), fmt(c_kanna)), ['stoned'])
    if q == 'bow_warning':
        return cell('punished_bow_warning', M, CPB + "Sanhedrin 60b:12 — the punished bow's WARNING is 34:14's clause (the punishment written at Deut 17:2-5); Sanhedrin 63a:2 (Abaye's three bowings) the same", ['stoned'])
    if q == 'no_bow_by_call':
        return cell(ORD_NOBOW, P, "23:24 'you shall not bow to their gods nor serve them nor do after their deeds' — the first seat's three: cold_run_ordinances.land(no_bow) -> %r [IMPORT, live call]; 34:14 keeps the bow alone with the jealousy clause" % (ORD_NOBOW,), ['stoned'])
    if q == 'court_error_bow':
        return cell('liable_part_uprooted', A, "Mishnah Horayot 1:3 — a court that ruled 'there is idolatry in the Torah but the BOWER is exempt' is LIABLE (part uprooted, not the body); Horayot 4a:20 (opened): 'but bowing is WRITTEN — you shall not bow to another god (34:14)!' — the explicit clause is what makes the exemption partial", ['bears_sin'])
    if q == 'whoring_three':
        return cell(c_zanu, I, "'whore after their gods' — 'after their gods' (masc.) at %s, 'after their gods' (fem.) at %s, the feminine twice in 34:16: three whoring clauses in two verses, the Torah's only seats of the verb-with-'after' in this form" % (fmt(c_zanu[0]), fmt(c_zanu[1])), ['intermarriage_barred'])
    if q == 'eat_sacrifice':
        return cell(1, I, "34:15 'and he will CALL you and you will EAT of his sacrifice' — 'and you eat of his sacrifice' a hapax: the inhabitant's INVITATION is the clause's trigger, the food's source unstated", ['barred_from_it'])
    if q == 'invitation_is_eating':
        return cell('the_invitation_is_the_eating', M, "Avodah Zarah 8a:17 (opened) — R. Yishmael: a gentile's feast for his son with all the Jews of his town invited — 'though they eat their own and drink their own and their own servant stands before them, the verse counts it as if they ate of the sacrifices of the dead, as it says (34:15) and he will call you and you will eat of his sacrifice' — the ink's verb 'call' read as the whole trigger", ['barred_from_it'])
    if q == 'sheet_az_2_3':
        return cell('sacrifices_of_the_dead', A, "Mishnah Avodah Zarah 2:3 — meat coming OUT of an idol's house is forbidden 'as the sacrifices of the dead' (R. Akiva): 34:15's 'his sacrifice' the class; the wine and the hides the descendant's list (data)", ['barred_from_it'])
    if q == 'daughters_two_seats':
        return cell(c_daughters, I, "34:16 'and you take OF THEIR DAUGHTERS FOR YOUR SONS' at %s; Deut 7:3 'his daughter you shall not take for your son' at %s — the ban's two Torah seats, the second seat of the covenant and the third of the Torah" % (fmt(c_daughters[0]), fmt(c_daughters[1])), ['intermarriage_barred'])
    if q == 'intermarriage_channels':
        return cell('seven_nations_by_torah_rest_by_decree', M, "Avodah Zarah 36b:9 (opened) — the Torah's ban (34:16, Deut 7:3) is the SEVEN NATIONS'; the court of Shammai and Hillel extended it to all; the coupler with an Aramean woman — 'a law to Moses from Sinai: zealots strike him' — the ban's channels named at the verse", ['intermarriage_barred'])
    if q == 'child_follows_mother':
        return cell('as_she_is', A, "Mishnah Kiddushin 3:12 — 'whoever has no betrothal with him or with others, the child is AS SHE IS: the child of a maidservant or of a gentile woman' — 34:16's 'they make YOUR SONS whore' (the son of the foreign mother called yours only to be whored away; Deut 7:4's 'he will turn your son' the tradition's seat)", ['intermarriage_barred'])
    if q == 'molten_two_seats':
        return cell(c_elohei_masekhah, I, "34:17 'MOLTEN GODS you shall not make for yourself' — the phrase at %s and, with the vav, at %s (Lev 19:4) alone; the molten-word in the Torah at %d seats (%s): the calf's own ban restated in the covenant" % (fmt(c_elohei_masekhah[0]), fmt(c_elohei_masekhah[1]), len(c_masekhah), fmt(c_masekhah)), ['molten_image_barred'])
    if q == 'inserted_neighbor':
        return cell('despising_the_festivals_as_idolatry_by_adjacency', M, "Makkot 23a:4 and Pesachim 118a:12 (opened) — R. Elazar b. Azaryah: 'whoever despises the festivals is as one who worships idols, as it says molten gods you shall not make (34:17) and NEXT TO IT the feast of unleavened bread you shall keep (34:18)' — the juxtaposition ONLY THE SECOND SEAT HAS (23:14-15 has no idol clause before the feast): the repeat's inserted neighbor legislates", ['molten_image_barred'])
    if q == 'inserted_verses':
        return cell(R_INSERTED, I, "the second seat's verses with NO first seat in 23:12-19: %s — the molten-gods clause before the feasts and the pilgrimage's warranty inside them; every other verse of 34:18-26 has a counterpart" % (R_INSERTED,), ['molten_image_barred', 'pilgrim_land_guarded'])
    if q == 'sheet_az_4_4':
        return cell('forbidden_once_worshipped', A, "Mishnah Avodah Zarah 4:4 — 'an Israelite's idol is not forbidden until it is WORSHIPPED' — the calf: made at 32:4, worshipped at 32:6 and 32:8; Avodah Zarah 53b:10 (opened): 'these are your gods' — they desired many gods", ['molten_image_barred'])
    if q == 'sheet_az_4_2':
        return cell('altar_class_forbidden', A, "Mishnah Avodah Zarah 4:2 — found on an idol 'whatever is offered on the altar' is forbidden: 32:6's burnt and peace offerings and 34:15's 'his sacrifice' the ink's own altar-classes at the idol", ['barred_from_it'])
    if q == 'sheet_az_3_5':
        return cell('made_objects_not_the_ground', A, "Mishnah Avodah Zarah 3:5 — the mountains permitted, the asherah forbidden 'because a human hand made it': 34:13's three objects are all made (altars, pillars, asherim); the ground is not in the verse", ['demolished'])
    if q == 'covenant_thirteen':
        return cell('never_returns_empty', M, CVB + "Rosh Hashanah 17b:7 — 34:10 'behold I cut a covenant' with the thirteen attributes: 'they do not return empty'", ['covenant_cut'])
    return cell('no_case', I, '', [FX.NONE])

# ---- F2: THE SECOND SEAT — 34:18-26 against 23:12-19 and 13:12-13, the same functions called twice ---------------
def repeats(q):
    if q == 'jaccard':
        return cell(R_JAC, I, "the eight clause-pairs aligned by normalized token overlap: %s — the kid clause identical (1.0), the matzah and the appearing near (0.7), the rest, the feasts, and the firstborn's first verse far (about 0.25): the second seat rewrites more than it repeats" % (R_JAC,), [FX.NONE])
    if q == 'kid_identical':
        return cell(True, I, "34:26 == 23:19 TOKEN FOR TOKEN (twelve tokens): 'the first of the first fruits of your land you shall bring to the house of the LORD your God; you shall not boil a kid in its mother's milk' — the one clause-pair the second seat copies unchanged (Deut 14:21 the third seat)", ['restores', 'barred_from_it'])
    if q == 'kid_by_call':
        return cell(CAL_KID, P, "the kid clause's three bans by call — cold_run_calendar.kid_in_milk(cook / eat / benefit) -> %r [IMPORT, live call]: the same function at its second seat (Kiddushin 57b:9, Chullin 115b:1 credited: three seats, three bans)" % (CAL_KID,), ['barred_from_it'])
    if q == 'first_fruits_by_call':
        return cell(CAL_FF, P, "34:26 'the first of the first fruits of your land' — cold_run_calendar.first_fruits -> %r [IMPORT, live call]; the appointed-times engine links the same: MO.two_loaves()['first_fruits_link'] -> %r" % (CAL_FF, MO_FF_LINK), ['restores'])
    if q == 'feasts_delta':
        return cell(R_DELTA['feasts'], I, "34:22 against 23:16 — the second seat ADDS %s and DROPS %s: the harvest feast renamed WEEKS, its grain named WHEAT, 'the turn of the year' for 'the year's going out', and the ingathering spelled plene (%s) where the first seat spells it defective (%s)" % (R_DELTA['feasts'][0], R_DELTA['feasts'][1], fmt(c_asif[0]), fmt(c_asif[1])), ['appearance_owed'])
    if q == 'weeks_consonants':
        return cell(c_weeks, I, "'the feast of WEEKS' (וחג שבעת) at %s alone — and the same consonants 'a feast of SEVEN days' (חג שבעת ימים) at %s: 'shavuot' and 'shiv'at' share a written form the vowels divide (Onkelos: weeks); the first seat's 'the feast of the HARVEST' at %s a hapax" % (fmt(c_weeks[0]), fmt(c_weeks[1]), fmt(c_weeks[2])), ['appearance_owed'])
    if q == 'wheat_two_loaves':
        return cell('two_loaves_of_wheat_precede_bikkurim', M, "Menachot 84b:4 (opened) — 'the feast of weeks, the first fruits of the WHEAT harvest' (34:22): the two loaves are of wheat and precede the first fruits; 'the barley harvest from where? — the feast of the harvest, the first fruits of your labors (23:16)': the two seats read as two grains, the repeat's added token fixing the loaves' grain", ['accepted'])
